import{_ as n,o as s,c as r,ag as t}from"./chunks/framework.C15dTZqp.js";const g=JSON.parse('{"title":"Les exercices de la journée","description":"","frontmatter":{},"headers":[],"relativePath":"handout-06-exercices.md","filePath":"handout-06-exercices.md","handout":{"fichier":"handout-06-exercices.md","markdown":"# Handout — Les exercices de la journée\\n\\n**Speed training IA · Zenika · supports d\'exercices**\\n\\nLes consignes et les prompts de départ des exercices en salle. Faites-les dans l\'assistant que vous utilisez habituellement (version entreprise), sur un sujet de votre métier si vous le pouvez.\\n\\n## Exercice 1 — Regenerate (4 min)\\n\\n**But** : sentir que la réponse varie, et que quelques mots changent tout.\\n\\n1. Écrivez une demande métier courte, volontairement **floue**.\\n2. Relancez-la **3 fois**. Notez ce qui reste stable.\\n3. Ajoutez **une seule** contrainte : cible, délai, canal ou format.\\n4. Relancez. Qu\'est-ce qui a le plus bougé : le ton, la structure, ou carrément l\'objectif ?\\n\\n```text\\nRédige une user story pour réduire les abandons de réservation.\\n```\\n\\npuis :\\n\\n```text\\nRédige une user story pour réduire les abandons de réservation\\nsur mobile.\\n```\\n\\nAutres points de départ : « Prépare une synthèse d\'atelier pour une équipe produit » (+ « en 5 puces, pour un comité de direction ») ; « Rédige un email pour annoncer un changement de logiciel » (+ « pour des équipes terrain, en 120 mots max »).\\n\\n## Exercice 2 — Du flou au brief (15 min)\\n\\n**But** : faire produire une structure, la corriger, puis seulement demander le livrable.\\n\\n1. Partez d\'un besoin métier **flou** de votre quotidien.\\n2. Demandez à l\'IA un **brief structuré**, pas le livrable.\\n3. Corrigez **2 ou 3 champs**.\\n4. Demandez le **livrable** : user story, synthèse, plan d\'action.\\n\\n```text\\nOn veut réduire les abandons de réservation sur mobile.\\nPropose-moi d\'abord un brief : objectif, cible, contraintes,\\nformat attendu. Ne rédige pas encore la user story.\\n```\\n\\npuis, une fois le brief corrigé :\\n\\n```text\\nBrief validé. Rédige maintenant la user story\\navec 3 critères d\'acceptation.\\n```\\n\\n**Pour le débrief** : montrez le brief, pas le rendu. Qu\'est-ce qu\'il vous a forcé à clarifier ?\\n\\n## Exercice 3 — Extraire (10 min)\\n\\n**But** : transformer une session en artefact réutilisable.\\n\\n1. Prenez une conversation un peu **longue** : celle de l\'exercice précédent, ou n\'importe quelle conversation récente (préparation de réunion, rédaction d\'un mail…).\\n2. Demandez une **extraction ciblée**, pas un résumé.\\n3. **Relisez** et corrigez : qu\'est-ce qui manquait, qu\'est-ce qui est faux ?\\n4. Gardez le résultat : c\'est votre premier **artefact**.\\n\\n```text\\nExtrais de cette conversation, en 3 listes courtes :\\n- les décisions prises,\\n- les risques identifiés,\\n- les prochaines actions (qui, quoi).\\nN\'invente rien : si une liste est vide, dis-le.\\n```\\n\\n**Pour le débrief** : l\'extraction a-t-elle retrouvé l\'essentiel ? Qu\'avez-vous dû corriger ?\\n\\n## Exercice 4 — De l\'interview au PRD (10 min)\\n\\nLe support est dans le handout **« Exercice : de l\'interview au PRD »**.\\n"}}'),i={name:"handout-06-exercices.md"};function a(o,e,l,u,c,d){return s(),r("div",null,[...e[0]||(e[0]=[t("",24)])])}const m=n(i,[["render",a]]);export{g as __pageData,m as default};
